using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
public partial class AudioOptionalWorkflowOperations
{
    public LineEdit field(Node o,Node parent,string label,string text,bool secret)
    {
        Label(Workspace(o),parent,label);var field=new LineEdit{Text=text,Secret=secret,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};parent.AddChild(field);return field;
    }
    public LineEdit path(Node o,Node parent,string label,string key,string[] filters)
    {
        var w=Workspace(o);Label(w,parent,label);var row=new HBoxContainer();parent.AddChild(row);var input=new LineEdit{Text=S(Dict(o,"settings"),key),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};row.AddChild(input);Button(w,row,"Browse\u2026",()=>{var picker=new FileDialog{Access=FileDialog.AccessEnum.Filesystem,FileMode=FileDialog.FileModeEnum.OpenFile,Filters=filters,UseNativeDialog=true};o.AddChild(picker);picker.FileSelected+=value=>{if(GodotObject.IsInstanceValid(input))input.Text=value;picker.QueueFree();};picker.Canceled+=picker.QueueFree;picker.PopupCenteredRatio(.7f);});return input;
    }
    public void configure(Node o)
    {
        var w=Workspace(o);var dialog=Window(w,"Optional local speech & cloud setup",new Vector2I(700,560));var host=dialog["host"].As<Node>();var window=dialog["window"].As<Window>();Label(w,host,"Local transcription: install whisper.cpp and a compatible GGML model separately. Audio stays on this computer. Nothing downloads or runs until you choose Transcribe selected clip.");var cli=path(o,host,"whisper.cpp CLI","whisper",new[]{"*.exe ; Executable"});var model=path(o,host,"GGML model","model",new[]{"*.bin ; GGML model"});Label(w,host,"Optional ElevenLabs speech: requires your own account, quota and authorized voice ID. Every generation requires separate send/cost/voice confirmations. No account or paid request is created here.");var voice=field(o,host,"Voice ID",S(Dict(o,"settings"),"voice_id"),false);var password=field(o,host,"API key (stored only in Windows Credential Manager)","",true);var actions=new HFlowContainer();host.AddChild(actions);
        var save=Button(w,actions,"Store key securely",()=>{if(password.Text.Trim().Length==0){Notice(w,"Enter a key to store.");return;}string secret=password.Text.Trim();password.Clear();Request(o,"vault",job=>{using var vault=new AudioCredentialVaultOperations();return vault.request("write","elevenlabs",secret,job);});});using var available=new AudioCredentialVaultOperations();save.Disabled=!available.available();var remove=Button(w,actions,"Remove stored key",()=>{var confirmation=new ConfirmationDialog{DialogText="Remove only the Kiwi Studios ElevenLabs credential from Windows Credential Manager?"};o.AddChild(confirmation);confirmation.Confirmed+=()=>{Request(o,"vault",job=>{using var vault=new AudioCredentialVaultOperations();return vault.request("delete","elevenlabs","",job);});confirmation.QueueFree();};confirmation.Canceled+=confirmation.QueueFree;confirmation.PopupCentered();});remove.Disabled=!available.available();Button(w,host,"Save tool paths & voice ID",()=>{var settings=new Settings{["whisper"]=cli.Text.Trim(),["model"]=model.Text.Trim(),["voice_id"]=voice.Text.Trim()};o.Set("settings",settings);using var config=new ConfigFile();foreach(var key in settings.Keys)config.SetValue("tools",key.AsString(),settings[key]);DirAccess.MakeDirRecursiveAbsolute(ProjectSettings.GlobalizePath(Config.GetBaseDir()));if(config.Save(Config)!=Error.Ok)Notice(w,"Could not save optional-tool settings.");else window.QueueFree();});
    }
    public void speech(Node o)
    {
        var w=Workspace(o);var source=context(o);var dialog=Window(w,"Optional cloud speech · review before sending",new Vector2I(690,580));var host=dialog["host"].As<Node>();var window=dialog["window"].As<Window>();Label(w,host,"Provider: ElevenLabs · Model: eleven_multilingual_v2 · Text only. No selected clip audio is uploaded. Pricing depends on your provider plan; Kiwi cannot quote or cap the charge. The request may use paid quota. Maximum 3000 characters; results limited to three minutes.");var prompt=new TextEdit{CustomMinimumSize=new Vector2(0,150),SizeFlagsVertical=Control.SizeFlags.ExpandFill};host.AddChild(prompt);var voice=field(o,host,"Authorized voice ID",S(Dict(o,"settings"),"voice_id"),false);var send=new CheckBox{Text="I approve sending this text to ElevenLabs"};host.AddChild(send);var cost=new CheckBox{Text="I approve unknown cost / use of my provider quota"};host.AddChild(cost);var authorized=new CheckBox{Text="I am authorized to use this voice"};host.AddChild(authorized);Button(w,host,"Generate approved request",()=>{if(!current(o,source)){Notice(w,"The composition changed. Reopen the speech dialog.");return;}if(!send.ButtonPressed||!cost.ButtonPressed||!authorized.ButtonPressed){Notice(w,"All three confirmations are required before any provider request.");return;}var request=new Settings{["task"]="speech",["model"]="eleven_multilingual_v2",["prompt"]=prompt.Text,["voice_id"]=voice.Text.Trim()};var consent=new Settings{["send_request"]=true,["unknown_cost"]=true,["voice_authorized"]=true};string token=remember(o,"speech",source);var service=Field<RefCounted>(o,"service");Request(o,"speech",job=>{using var provider=new AudioProviderServiceOperations();var result=provider.run(service,"elevenlabs",request,consent,job);result["token"]=token;return result;});window.QueueFree();Field<Godot.Label>(w,"status").Text="Generating approved cloud speech\u2026";});Button(w,host,"Configure provider credential",()=>configure(o));
    }
}
